(() => {
 const mapping = new Map(window.EmojiArtwork.map(x => [x.emoji, x]));
 const ordered = [...mapping.keys()].sort((a,b) => b.length-a.length);
 const expression = new RegExp(ordered.map(x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'gu');
 function replace() {
  const walker = document.createTreeWalker(document.getElementById('preview'), NodeFilter.SHOW_TEXT);
  const nodes = []; while(walker.nextNode()) nodes.push(walker.currentNode);
  for(const node of nodes) {
   if(node.parentElement.closest('script,style,textarea,input,option,code,[data-keep-emoji]')) continue;
   const value = node.nodeValue; expression.lastIndex=0;
   if(!expression.test(value)) continue; expression.lastIndex=0;
   const fragment = document.createDocumentFragment(); let offset=0;
   for(const match of value.matchAll(expression)) {
    fragment.append(document.createTextNode(value.slice(offset,match.index)));
    const item=mapping.get(match[0]), image=document.createElement('img');
    image.src=item.src; image.alt=match[0];
    image.className='emoji-artwork'; image.width=64; image.height=64;
    image.onerror=()=>{const fallback=document.createElement('span');fallback.dataset.keepEmoji='';fallback.textContent=match[0];image.replaceWith(fallback);};
    fragment.append(image); offset=match.index+match[0].length;
   }
   fragment.append(document.createTextNode(value.slice(offset))); node.replaceWith(fragment);
  }
 }
 const observer=new MutationObserver(replace);
 observer.observe(document.getElementById('preview'), {childList:true,subtree:true}); replace();
})();
